using System;
using System.Collections.Generic;
using System.IO;
using System.Text;
using BepInEx;

namespace LOMAssistant;

/// <summary>
/// velvetcakes 的英文补丁（LoM_en）：XUnity.AutoTranslator 加补丁自带的翻译文件（BepInEx\Translation\en\Text\ 下的 txt，一行「中文=英文」）。
/// 界面是英语时，本 Mod 窗口里来自游戏的文字（数值名、人名、地点、任务名……）查这份文件，和打了补丁的游戏叫法一致。
/// 只读玩家电脑上装着的文件，Mod 里不带它的译文。
/// </summary>
public static class XUnityTranslations
{
	/// <summary>补丁的翻译文件所在的文件夹。</summary>
	public static string Folder => Path.Combine(Paths.BepInExRootPath, "Translation", "en", "Text");

	/// <summary>文件夹里有补丁的翻译文件（XUnity 自己机翻记下来的 _AutoGeneratedTranslations 不算）。</summary>
	public static bool PatchFilesPresent
	{
		get
		{
			try
			{
				if (!Directory.Exists(Folder))
				{
					return false;
				}
				foreach (string file in Directory.GetFiles(Folder, "*.txt", SearchOption.AllDirectories))
				{
					if (!IsAutoGenerated(file))
					{
						return true;
					}
				}
			}
			catch (Exception)
			{
			}
			return false;
		}
	}

	private static bool IsAutoGenerated(string file) => Path.GetFileName(file).StartsWith("_AutoGenerated", StringComparison.OrdinalIgnoreCase);

	/// <summary>读出全部「中文 → 英文」；没装补丁时为空。正则（r: / sr:）、按场景限定（#set …）的条目不收。</summary>
	public static Dictionary<string, string> Load()
	{
		var map = new Dictionary<string, string>(StringComparer.Ordinal);
		try
		{
			if (!Directory.Exists(Folder))
			{
				return map;
			}
			foreach (string file in Directory.GetFiles(Folder, "*.txt", SearchOption.AllDirectories))
			{
				if (IsAutoGenerated(file))
				{
					continue;
				}
				foreach (string raw in File.ReadAllLines(file, Encoding.UTF8))
				{
					string line = raw.Trim();
					if (line.Length == 0 || line.StartsWith("//") || line.StartsWith("#") || line.StartsWith("r:") || line.StartsWith("sr:"))
					{
						continue;
					}
					int eq = SplitAt(line);
					if (eq <= 0 || eq == line.Length - 1)
					{
						continue;
					}
					string zh = Unescape(line.Substring(0, eq)), en = Unescape(line.Substring(eq + 1));
					if (zh.Length > 0 && en.Length > 0 && !map.ContainsKey(zh))
					{
						map[zh] = en;
					}
				}
			}
			FileLogger.Log($"[英文补丁] 读了翻译文件 {map.Count} 条（{Folder}）");
		}
		catch (Exception e)
		{
			FileLogger.LogWarning("[英文补丁] 读翻译文件失败: " + e.Message);
		}
		return map;
	}

	// 第一个没被反斜杠转义的「=」
	private static int SplitAt(string line)
	{
		for (int i = 0; i < line.Length; i++)
		{
			if (line[i] == '\\')
			{
				i++;
			}
			else if (line[i] == '=')
			{
				return i;
			}
		}
		return -1;
	}

	private static string Unescape(string text)
	{
		if (text.IndexOf('\\') < 0)
		{
			return text;
		}
		var sb = new StringBuilder(text.Length);
		for (int i = 0; i < text.Length; i++)
		{
			char c = text[i];
			if (c == '\\' && i + 1 < text.Length)
			{
				char n = text[++i];
				sb.Append(n == 'n' ? '\n' : n == 'r' ? '\r' : n == 't' ? '\t' : n);
			}
			else
			{
				sb.Append(c);
			}
		}
		return sb.ToString();
	}
}
